def naira(n): return '₦'+format(n,',')
def make_table(rows,widths):
    data=[]
    for r,row in enumerate(rows): data.append([P(str(v),'TableHead' if r==0 else 'TableCell') for v in row])
    t=Table(data,colWidths=widths,repeatRows=1,hAlign='LEFT')
    t.setStyle(TableStyle([('GRID',(0,0),(-1,-1),.35,HexColor('#D6DEE3')),('BACKGROUND',(0,0),(-1,0),NAVY),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,PALE]),('VALIGN',(0,0),(-1,-1),'MIDDLE'),('LEFTPADDING',(0,0),(-1,-1),6),('RIGHTPADDING',(0,0),(-1,-1),6),('TOPPADDING',(0,0),(-1,-1),5),('BOTTOMPADDING',(0,0),(-1,-1),5)]))
    return t
class Numbered(canvas.Canvas):
    def __init__(self,*a,**kw): canvas.Canvas.__init__(self,*a,**kw); self.states=[]
    def showPage(self): self.states.append(dict(self.__dict__)); self._startPage()
    def save(self):
        total=len(self.states)
        for st in self.states:
            self.__dict__.update(st); w,h=A4; self.saveState(); self.setStrokeColor(HexColor('#D9E2E7')); self.line(20*mm,15*mm,w-20*mm,15*mm); self.setFont('ArielLC',7.5); self.setFillColor(MUTED); self.drawString(20*mm,10.5*mm,'LODGECORE PMS LTD  |  CONFIDENTIAL MANAGEMENT PROPOSAL'); self.drawRightString(w-20*mm,10.5*mm,f'{self._pageNumber} / {total}'); self.restoreState(); canvas.Canvas.showPage(self)
        canvas.Canvas.save(self)
def header(c,doc):
    w,h=A4; c.saveState()
    if doc.page==1:
        c.setFillColor(NAVY); c.rect(0,0,w,h,fill=1,stroke=0); c.setFillColor(TEAL); c.rect(0,0,14*mm,h,fill=1,stroke=0); c.setFillColor(GOLD); c.rect(14*mm,0,2*mm,h,fill=1,stroke=0); c.setFillColor(GOLD); c.circle(w-25*mm,h-24*mm,12*mm,fill=0,stroke=1); c.setFont('ArielLC-Bold',8); c.drawCentredString(w-25*mm,h-27*mm,'LC')
    else:
        c.setFillColor(NAVY); c.rect(0,h-7*mm,w,7*mm,fill=1,stroke=0); c.setFillColor(GOLD); c.rect(20*mm,h-7*mm,14*mm,1.3*mm,fill=1,stroke=0)
    c.restoreState()
